/** Where a machine runs */
export interface EnvironmentRow {
  /** The code other tables point to: a short word that does not change */
  readonly code: string;
  /** What a person is shown for the code */
  readonly label: string;
  /** What the code means, where the label is not enough */
  readonly description: string | null;
}

/** What an insert into environment takes: what the database fills may be left out. */
export interface EnvironmentInsert {
  readonly code: string;
  readonly label: string;
  readonly description?: string | null;
}

/** The key of a row of environment. */
export type EnvironmentKey = { readonly code: string };

/** Where a machine runs */
export const environment = defineTable<EnvironmentRow, EnvironmentInsert, "environment">({
  alias: "environment",
  name: "environment",
  columns: {
    code: "code",
    label: "label",
    description: "description",
  },
  primaryKey: ["code"],
});

/** A program that acts for itself, with a person or a group accountable for it */
export interface MachineRow {
  /** The principal the machine is */
  readonly principalId: string;
  /** What kind of program it is */
  readonly machineKind: "service" | "workload" | "pipeline" | "integration" | "bot";
  /** What it is for */
  readonly purpose: string;
  /** Where it runs */
  readonly environmentCode: string | null;
  /** Whether it is an account kept for emergencies, whose every use is reviewed */
  readonly isBreakGlass: boolean;
  /** The longest a credential of the machine may live */
  readonly maxCredentialDays: number | null;
  /** When the machine must next be reviewed by its owner */
  readonly reviewBy: Timestamp | null;
}

/** What an insert into machine takes: what the database fills may be left out. */
export interface MachineInsert {
  readonly principalId: string;
  readonly machineKind: "service" | "workload" | "pipeline" | "integration" | "bot";
  readonly purpose: string;
  readonly environmentCode?: string | null;
  readonly isBreakGlass: boolean;
  readonly maxCredentialDays?: number | null;
  readonly reviewBy?: Timestamp | null;
}

/** The key of a row of machine. */
export type MachineKey = { readonly principalId: string };

/** A program that acts for itself, with a person or a group accountable for it */
export const machine = defineTable<MachineRow, MachineInsert, "machine">({
  alias: "machine",
  name: "machine",
  columns: {
    principalId: "principal_id",
    machineKind: "machine_kind",
    purpose: "purpose",
    environmentCode: "environment_code",
    isBreakGlass: "is_break_glass",
    maxCredentialDays: "max_credential_days",
    reviewBy: "review_by",
  },
  primaryKey: ["principalId"],
  foreignKeys: [
    { columns: ["principalId"], references: "principal", referencesColumns: ["principalId"] },
    { columns: ["environmentCode"], references: "environment", referencesColumns: ["code"] },
  ],
});

/** What a platform vouches for about a workload, so that a machine proves itself by it instead of by a secret */
export interface WorkloadIdentityRow {
  /** What identifies the binding, made by the application */
  readonly workloadIdentityId: string;
  /** What vouches for it */
  readonly issuerKind: "spiffe" | "kubernetes" | "oidc" | "cloud" | "mtls";
  /** The issuer */
  readonly issuer: string;
  /** The workload's name for the issuer: a SPIFFE ID, a service account, a subject, a thumbprint */
  readonly subject: string;
  /** The trust domain */
  readonly trustDomain: string | null;
  /** The audience the proof must be for */
  readonly audience: string | null;
  /** Whether the binding is applied */
  readonly status: "active" | "retired";
  /** A hash of the issuer and the subject, unique */
  readonly bindingKey: string;
  /** The machine the workload is */
  readonly machinePrincipalId: string;
}

/** What an insert into workload_identity takes: what the database fills may be left out. */
export interface WorkloadIdentityInsert {
  readonly workloadIdentityId: string;
  readonly issuerKind: "spiffe" | "kubernetes" | "oidc" | "cloud" | "mtls";
  readonly issuer: string;
  readonly subject: string;
  readonly trustDomain?: string | null;
  readonly audience?: string | null;
  readonly status: "active" | "retired";
  readonly bindingKey: string;
  readonly machinePrincipalId: string;
}

/** The key of a row of workload_identity. */
export type WorkloadIdentityKey = { readonly workloadIdentityId: string };

/** What a platform vouches for about a workload, so that a machine proves itself by it instead of by a secret */
export const workloadIdentity = defineTable<WorkloadIdentityRow, WorkloadIdentityInsert, "workloadIdentity">({
  alias: "workloadIdentity",
  name: "workload_identity",
  columns: {
    workloadIdentityId: "workload_identity_id",
    issuerKind: "issuer_kind",
    issuer: "issuer",
    subject: "subject",
    trustDomain: "trust_domain",
    audience: "audience",
    status: "status",
    bindingKey: "binding_key",
    machinePrincipalId: "machine_principal_id",
  },
  primaryKey: ["workloadIdentityId"],
  foreignKeys: [
    { columns: ["machinePrincipalId"], references: "machine", referencesColumns: ["principalId"] },
  ],
});

